urlset:
{% spaceless %}
{% for url in urlset %}

    {{ url.location }}
    {% if url.lastmod %}{{ url.lastmod|date:"Y-m-d" }}{% endif %}
    {% if url.changefreq %}{{ url.changefreq }}{% endif %}
    {% if url.priority %}{{ url.priority }}{% endif %}
    {% for img_url, img_alt in url.item.sitemap_images %}{% if img_url|slice:":4" == "http" %}{{ img_url }}{% else %}https://{{ SITE_DOMAIN }}{{ img_url }}{% endif %}{{ img_alt }}{% endfor %}

{% endfor %}
{% endspaceless %}
